```java
public static int fee(int minutes) {
    if (minutes <= 30) {
        return 0;
    }
    int hours = (minutes + 59) / 60;
    int cost = hours * 2;
    if (cost > 14) {
        cost = 14;
    }
    return cost;
}
```

```java
public static int longestStay(int budget) {
    for (int m = 1440; m >= 0; m--) {
        if (fee(m) <= budget) {
            return m;
        }
    }
    return 0;
}
```

```java
public class Thermostat {
    private int min;
    private int max;
    private int setting;
    private int changes;
    public Thermostat(int min, int max, int start) {
        this.min = min;
        this.max = max;
        setting = start;
        changes = 0;
    }
    public void raise(int amount) {
        update(Math.min(max, setting + amount));
    }
    public void lower(int amount) {
        update(Math.max(min, setting - amount));
    }
    private void update(int next) {
        if (next != setting) {
            changes++;
        }
        setting = next;
    }
    public int getSetting() {
        return setting;
    }
    public int getChanges() {
        return changes;
    }
}
```

```java
public int totalTime(String artist) {
    int total = 0;
    for (Song s : songs) {
        if (s.getArtist().equals(artist)) {
            total += s.getSeconds();
        }
    }
    return total;
}
```

```java
public int removeShort(int min) {
    int removed = 0;
    for (int i = songs.size() - 1; i >= 0; i--) {
        if (songs.get(i).getSeconds() < min) {
            songs.remove(i);
            removed++;
        }
    }
    return removed;
}
```

```java
public boolean isPeak(int r, int c) {
    int h = heights[r][c];
    if (r > 0 && heights[r - 1][c] >= h) return false;
    if (r < heights.length - 1 && heights[r + 1][c] >= h) return false;
    if (c > 0 && heights[r][c - 1] >= h) return false;
    if (c < heights[0].length - 1 && heights[r][c + 1] >= h) return false;
    return true;
}
```

```java
public int countPeaks() {
    int count = 0;
    for (int r = 0; r < heights.length; r++) {
        for (int c = 0; c < heights[0].length; c++) {
            if (isPeak(r, c)) {
                count++;
            }
        }
    }
    return count;
}
```
